//! The bridge between `powerup-core` and the macOS app, generated by uniffi.
//!
//! Every exported function runs the core inside [`contain`], so a panic in
//! the core becomes [`CoreBridgeError::Panicked`] on the Swift side instead
//! of unwinding into the app (stage 2.1, "total surface").

use std::panic::{self, AssertUnwindSafe};
use std::sync::{Mutex, MutexGuard, PoisonError};

use powerup_core::{probe, CoreError};

uniffi::setup_scaffolding!();

mod acp;
mod config;
mod device;
mod harness;
mod mapping;
mod session;

/// An error a core call reports to Swift.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Error)]
pub enum CoreBridgeError {
    /// The core reported a failure.
    Failed { message: String },
    /// The core panicked; the panic was caught at the bridge.
    Panicked { message: String },
}

impl std::fmt::Display for CoreBridgeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CoreBridgeError::Failed { message } => write!(f, "{message}"),
            CoreBridgeError::Panicked { message } => write!(f, "core panicked: {message}"),
        }
    }
}

impl std::error::Error for CoreBridgeError {}

impl From<CoreError> for CoreBridgeError {
    fn from(error: CoreError) -> Self {
        match error {
            CoreError::Failed { message } => CoreBridgeError::Failed { message },
        }
    }
}

/// Runs one core call, mapping its error and catching any panic.
fn contain<T>(call: impl FnOnce() -> Result<T, CoreError>) -> Result<T, CoreBridgeError> {
    match panic::catch_unwind(AssertUnwindSafe(call)) {
        Ok(result) => result.map_err(CoreBridgeError::from),
        Err(payload) => {
            let message = if let Some(text) = payload.downcast_ref::<&str>() {
                (*text).to_string()
            } else if let Some(text) = payload.downcast_ref::<String>() {
                text.clone()
            } else {
                "unknown panic".to_string()
            };
            Err(CoreBridgeError::Panicked { message })
        }
    }
}

/// Locks an object's state. A panic caught by [`contain`] while the lock was
/// held poisons it. The next call takes the state as the panicking call left
/// it: a core bug may have left one call's update half done, which costs at
/// most that session, whereas refusing the lock would fail every later call
/// and brick the object for the rest of the app run.
fn locked<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(PoisonError::into_inner)
}

/// Bridge probe: returns `text` unchanged.
#[uniffi::export]
pub fn probe_echo(text: String) -> Result<String, CoreBridgeError> {
    contain(|| probe::echo(text))
}

/// Bridge probe: always fails with `message`.
#[uniffi::export]
pub fn probe_fail(message: String) -> Result<String, CoreBridgeError> {
    contain(|| probe::fail_with(message))
}

/// Bridge probe: the core panics with `message`; the bridge reports it.
#[uniffi::export]
pub fn probe_panic(message: String) -> Result<String, CoreBridgeError> {
    contain(|| probe::panic_with(message))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_core_panic_becomes_an_error() {
        assert_eq!(
            probe_panic("boom".to_string()),
            Err(CoreBridgeError::Panicked {
                message: "boom".to_string()
            })
        );
    }

    #[test]
    fn objects_survive_a_poisoned_lock() {
        let state = Mutex::new(vec![1]);
        let caught = contain(|| -> Result<(), CoreError> {
            let mut held = locked(&state);
            held.push(2);
            panic!("boom while holding the lock")
        });
        assert_eq!(
            caught,
            Err(CoreBridgeError::Panicked {
                message: "boom while holding the lock".to_string()
            })
        );
        assert!(state.is_poisoned());
        locked(&state).push(3);
        assert_eq!(*locked(&state), vec![1, 2, 3]);
    }

    #[test]
    fn a_core_error_is_mapped() {
        assert_eq!(
            probe_fail("nope".to_string()),
            Err(CoreBridgeError::Failed {
                message: "nope".to_string()
            })
        );
    }
}
